function fewestTurns(blocked: string[], target: string): number {
  const seen = new Set(blocked);
  if (seen.has("0000")) return -1;
  seen.add("0000");
  let level = ["0000"], turns = 0;
  while (level.length) {
    const next: string[] = [];
    for (const code of level) {
      if (code === target) return turns;
      for (let i = 0; i < 4; i++) {
        const d = +code[i];
        for (const nd of [(d + 1) % 10, (d + 9) % 10]) {
          const nb = code.slice(0, i) + nd + code.slice(i + 1);
          if (!seen.has(nb)) { seen.add(nb); next.push(nb); }
        }
      }
    }
    level = next;
    turns++;
  }
  return -1;
}

