  const dead = new Set(blocked);
  if (dead.has("0000") || dead.has(target)) return -1;
  if (target === "0000") return 0;
  let a = new Set(["0000"]), b = new Set([target]);
  const seen = new Set(["0000", target]);
  let turns = 0;
  while (a.size && b.size) {
    if (a.size > b.size) [a, b] = [b, a];
    turns++;
    const next = new Set<string>();
    for (const code of a) {
      for (let i = 0; i < 4; i++) {
        const d = +code[i];
        for (const nd of [(d + 1) % 10, (d + 9) % 10]) {
          const nb = code.slice(0, i) + nd + code.slice(i + 1);
          if (b.has(nb)) return turns;
          if (dead.has(nb) || seen.has(nb)) continue;
          seen.add(nb);
          next.add(nb);
        }
      }
    }
    a = next;
  }
  return -1;
}

